import React, {
  ElementType,
  forwardRef,
  MouseEventHandler,
  ReactElement,
  ReactEventHandler,
  ReactNode,
} from 'react';
import styled, { CSSObject } from 'styled-components';

import Animations from '@dynatrace/strato-design-tokens/animations';
import Borders from '@dynatrace/strato-design-tokens/borders';
import Colors from '@dynatrace/strato-design-tokens/colors';
import Spacings from '@dynatrace/strato-design-tokens/spacings';
import Typography from '@dynatrace/strato-design-tokens/typography';

import { useActionGroupContext } from './hooks/useActionGroupContext.js';
import { Button } from '../../../buttons/button/Button.js';
import { useFocusRing } from '../../../core/hooks/useFocusRing.js';
import type { CSSFocusStylesObject } from '../../../core/hooks/useFocusRing.js';
import type { DataTestId } from '../../../core/types/data-props.js';
import type { PolymorphicComponentProps } from '../../../core/types/polymorph.js';
import type { StylingProps } from '../../../core/types/styling-props.js';
import { mergeProps as _mergeProps } from '../../../core/utils/merge-props.js';
import { getTextStyle } from '../../../core/utils/styles/text-styles.js';
import { Menu } from '../../../navigation/menu/Menu.js';

// #region Typings
export interface ActionButtonOwnProps extends StylingProps, DataTestId {
  /**
   * Whether the action button is disabled.
   */
  disabled?: boolean;
  /**
   * Whether or not the ActionButton label is shown in the expanded header.
   * If set to false, the label is hidden and only shows in the collapsed menu.
   * If set to false and the prefixIcon is undefined, the label will be shown regardless.
   * @defaultValue true
   */
  showLabel?: boolean;
  /** If set to true, the item will not be moved into the menu in case of insufficient space. */
  pin?: boolean;
  /** Icon shown before the text of the ActionButton. */
  prefixIcon?: ReactElement;
  /** Whether or not the ActionButton is selected. */
  isSelected?: boolean;
  /**
   * Influences the spacings. Condensed is more compact.
   */
  density?: 'default' | 'condensed';
  /** Handler that is called when the ActionButton is interacted with. */
  onClick?: MouseEventHandler;
  /** Node to be displayed as ActionButton label. */
  children: ReactNode;
}

export type ActionButtonProps<E extends ElementType> =
  PolymorphicComponentProps<E, ActionButtonOwnProps>;
// #endregion

// #region Styled Components
const StyledActionButton = styled(Button)<{
  $focusStyle?: CSSFocusStylesObject;
}>(({ $isSelected, $focusStyle, $size, disabled }) => {
  const defaultStyles = {
    cursor: 'pointer',
    maxWidth: 'unset',
    ':hover': {
      color: Colors.Text.Neutral.Default,
      backgroundColor: Colors.Background.Field.Neutral.DefaultHover,
      textDecoration: 'none',
    },
    ':active': {
      color: Colors.Text.Neutral.Default,
      backgroundColor: Colors.Background.Field.Neutral.DefaultActive,
      textDecoration: 'none',
    },
    '&::after': {
      content: '" "',
      width: '16px',
      height: '2px',
      backgroundColor: Colors.Icon.Primary.Default,
      borderRadius: Borders.Radius.Surface.Default,
      position: 'absolute',
      left: '50%',
      opacity: 0,
      bottom: Spacings.Size0,
      transform: `translateX(-50%) translateY(${Spacings.Size0})`,
      transition: `width ${Animations.SlideOut.Duration.Fast} ${Animations.SlideOut.Easing}, opacity ${Animations.SlideOut.Duration.Fast} ${Animations.SlideOut.Easing}, transform ${Animations.SlideOut.Duration.Fast} ${Animations.SlideOut.Easing}`,
    },
  } as CSSObject;

  const selectedStyles = $isSelected ? selectedBaseStyles : defaultStyles;

  const disabledStyles = {
    cursor: 'default',
    color: Colors.Text.Neutral.Disabled,
  };

  const sizeStyles: CSSObject =
    $size === 'condensed'
      ? {
          gap: Spacings.Size2,
          paddingTop: Spacings.Size2,
          paddingBottom: Spacings.Size2,
          paddingLeft: Spacings.Size4,
          paddingRight: Spacings.Size4,
        }
      : {
          gap: Spacings.Size4,
          paddingTop: Spacings.Size6,
          paddingBottom: Spacings.Size6,
          paddingLeft: Spacings.Size8,
          paddingRight: Spacings.Size8,
        };

  return {
    position: 'relative',
    display: 'flex',
    gap: Spacings.Size4,
    borderRadius: Borders.Radius.Field.Default,
    backgroundColor: 'inherit',
    color: Colors.Text.Neutral.Default,
    border: 'none',
    fontSize: Typography.Text.Base.Default.Size,
    textDecoration: 'none',
    whiteSpace: 'nowrap',
    ...sizeStyles,
    ...getTextStyle('base-emphasized'),
    ...(disabled ? disabledStyles : selectedStyles),
    ...$focusStyle,
    /* This is necessary for the ActionGroup to prevent overflowing with
    ellipsis - otherwise the items wouldn't collapse into a menu when resizing */
    '.strato-button-label': {
      textOverflow: 'unset',
      overflow: 'visible',
      whiteSpace: 'unset',
    },
  };
});

export const selectedBaseStyles = {
  color: Colors.Text.Primary.Default,
  ':hover': {
    color: Colors.Text.Primary.Default,
    backgroundColor: Colors.Background.Field.Primary.DefaultHover,
    textDecoration: 'none',
  },
  ':active': {
    color: Colors.Text.Primary.Default,
    backgroundColor: Colors.Background.Field.Primary.DefaultActive,
    textDecoration: 'none',
  },
  '&::after': {
    content: '" "',
    width: '20px',
    height: '2px',
    backgroundColor: Colors.Icon.Primary.Default,
    borderRadius: Borders.Radius.Surface.Default,
    position: 'absolute',
    left: '50%',
    opacity: 1,
    bottom: 0,
    transform: `translateX(-50%) translateY(calc(${Spacings.Size2} * -1))`,
    transition: `width ${Animations.SlideIn.Duration.Fast} ${Animations.SlideIn.Easing}, opacity ${Animations.SlideIn.Duration.Fast} ${Animations.SlideIn.Easing}, transform ${Animations.SlideIn.Duration.Fast} ${Animations.SlideIn.Easing}`,
  },
} as CSSObject;
// #endregion

/**
 * An action button used in the ActionGroup.
 */
export const ActionButton: <E extends ElementType = 'button'>(
  props: ActionButtonProps<E>,
) => ReactElement | null = forwardRef(
  <E extends ElementType>(
    props: ActionButtonProps<E>,
    forwardedRef: typeof props.ref,
  ) => {
    const {
      showLabel = true,
      isSelected,
      children,
      prefixIcon,
      disabled,
      as,
      pin,
      onClick,
      density = 'default',
      className: consumerClassName,
      style: consumerStyle,
      'data-testid': dataTestId,
      ...remainingProps
    }: ActionButtonProps<E> = props;
    const { isCollapsed } = useActionGroupContext();
    const { focusProps, focusStyles } = useFocusRing();

    /* If the prefixIcon is set and showLabel is false, then the children are shown only in the collapsed version and hidden in the expanded one.
    If there is a prefixIcon and showLabel is true (default), we always show the children.
    If no prefixIcon is set, we always show the children regardless of the showLabel value (otherwise an empty button would be shown). */
    const showChildren = !prefixIcon || showLabel || isCollapsed;

    // The menu item can only be rendered inside a menu, so we have to conditionally render
    // either the menu item or a normal button.
    if (isCollapsed) {
      return (
        <Menu.Item<ElementType>
          ref={forwardedRef}
          as={as}
          disabled={disabled}
          $isSelected={isSelected}
          onSelect={(onClick ?? (() => null)) as ReactEventHandler}
          className={consumerClassName}
          style={consumerStyle}
          data-testid={dataTestId}
          {...remainingProps}
        >
          {prefixIcon && <Menu.ItemIcon>{prefixIcon}</Menu.ItemIcon>}
          {showChildren && children}
        </Menu.Item>
      );
    }

    const buttonProps = {
      disabled,
      onClick,
      $isSelected: isSelected,
      ref: forwardedRef,
      variant: 'default',
      $size: density,
      as: as ?? Button,
      className: consumerClassName,
      style: consumerStyle,
      'data-testid': dataTestId,
    };

    if (as) {
      return (
        <StyledActionButton
          $focusStyle={focusStyles}
          {..._mergeProps(
            // Need to cast this one as the inference of mergeProps would generate
            // a not allowed overlap. The remainingProps type is too complex due to the
            // polymorphic inheritance.
            remainingProps as Record<string, unknown>,
            focusProps,
            buttonProps,
          )}
        >
          {prefixIcon}
          {showChildren && children}
        </StyledActionButton>
      );
    }

    return (
      <StyledActionButton
        {..._mergeProps(buttonProps, remainingProps as Record<string, number>)}
      >
        <Button.Prefix>{prefixIcon}</Button.Prefix>
        {showChildren && children}
      </StyledActionButton>
    );
  },
);

(ActionButton as typeof ActionButton & { displayName: string }).displayName =
  'ActionGroup.Button';
